+/**
+  * @brief  测试无 UPG2 冷启动下连续 0x01/0x03 轮询及 0x1D(action=1) 均不置驻留位并允许跳 App
+  * @param  无
+  * @return 无返回值；任一断言不满足时通过 require_true 终止进程
+  */
+static void test_cold_boot_continuous_poll_allows_app_jump(void)
+{
+  uint8_t img[1024];
+  fw_trailer_t tr;
+  uint32_t img_crc = 0U;
+  build_mc_image_and_trailer(img, sizeof(img), &tr, &img_crc);
+  memcpy(s_sim_flash, img, sizeof(img));
+
+  /* 模拟无 UPG2 魔数的非升级复位进入 2.0s 探测窗口 */
+  s_sim_magic = 0UL;
+  s_jump_count = 0U;
+  s_reset_count = 0U;
+  boot_uart_ota_init();
+  require_true(boot_uart_ota_should_stay_in_boot() == 0U, "cold boot starts with stay_in_boot == 0");
+
+  /* 模拟 AP 守护进程每 500ms 连续 4 轮轮询只读 0x01 与 0x03 */
+  for (uint16_t i = 0U; i < 4U; i++)
+  {
+    uint32_t ping_token = 0x11223300UL + (uint32_t)i;
+    minimc_payload_pong_t pong_rsp;
+    send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_VERSION, (uint16_t)(60U + i * 2U), NULL);
+    require_true(s_last_tx_len == 30U && s_last_tx[5] == MINIMC_CMD_VERSION_REPORT, "poll 0x01 -> 0x02");
+    require_true(boot_uart_ota_should_stay_in_boot() == 0U, "repeated 0x01 keeps stay_in_boot == 0");
+
+    send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_PING, (uint16_t)(61U + i * 2U), &ping_token);
+    memcpy(&pong_rsp, &s_last_tx[12], sizeof(pong_rsp));
+    require_true(s_last_tx_len == 26U && pong_rsp.echo_token == ping_token, "poll 0x03 -> 0x04 token");
+    require_true(boot_uart_ota_should_stay_in_boot() == 0U, "repeated 0x03 keeps stay_in_boot == 0");
+    s_sim_systick += 500U;
+  }
+
+  /* 2.0s 探测窗口届满且未驻留时，主循环正常跳转至 0x08020000 有效 App */
+  if (boot_uart_ota_should_stay_in_boot() == 0U && is_app_valid(FLASH_APP_ADDR) != 0U)
+  {
+    jump_to_app(FLASH_APP_ADDR);
+  }
+  require_true(s_jump_count == 1U && s_last_jump_addr == FLASH_APP_ADDR, "2.0s window jumps to App");
+
+  /* 验证 0x1D(action=1) 普通软复位仅触发系统复位，不置位 stay_in_boot */
+  minimc_payload_sys_ctrl_t sc_reboot = {1U, 1U, 0U};
+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_SYSTEM_CONTROL, 70U, &sc_reboot);
+  require_true(s_last_tx[5] == MINIMC_CMD_ACK && s_reset_count == 1U, "0x1D(action=1) triggers reset");
+  require_true(boot_uart_ota_should_stay_in_boot() == 0U, "0x1D(action=1) keeps stay_in_boot == 0");
+}
+
+/**
+  * @brief  测试 UPG2 魔数、0x1D(action=2) 与合法 0x20 显式驻留及后续串口 OTA 恢复路径
+  * @param  无
+  * @return 无返回值；任一断言不满足时通过 require_true 终止进程
+  */
+static void test_explicit_stay_in_boot_triggers(void)
+{
+  uint8_t img[1024];
+  fw_trailer_t tr;
+  uint32_t img_crc = 0U;
+  build_mc_image_and_trailer(img, sizeof(img), &tr, &img_crc);
+
+  /* 1. UPG2 魔数命中驻留，且后续收到只读 0x01 不会清除已置位的驻留状态 */
+  s_sim_magic = BOOT_MC_UPGRADE_MAGIC_VAL;
+  boot_uart_ota_init();
+  require_true(boot_uart_ota_should_stay_in_boot() == 1U, "UPG2 sets stay_in_boot == 1");
+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_VERSION, 80U, NULL);
+  require_true(boot_uart_ota_should_stay_in_boot() == 1U, "0x01 preserves UPG2 stay_in_boot == 1");
+
+  /* 2. 无魔数冷启动后收到 0x1D(action=2) 显式置位 stay_in_boot == 1 */
+  s_sim_magic = 0UL;
+  boot_uart_ota_init();
+  require_true(boot_uart_ota_should_stay_in_boot() == 0U, "clean init before 0x1D(action=2)");
+  minimc_payload_sys_ctrl_t sc_stay = {2U, 1U, 0U};
+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_SYSTEM_CONTROL, 81U, &sc_stay);
+  require_true(s_last_tx[5] == MINIMC_CMD_ACK && boot_uart_ota_should_stay_in_boot() == 1U, "0x1D(2) stays");
+
+  /* 3. 无魔数冷启动：非法 0x20 拒绝不误锁驻留；合法 0x20 显式驻留并完成完整 OTA 恢复 */
+  boot_uart_ota_init();
+  s_jump_count = 0U;
+  minimc_payload_ota_start_t bad_req = {MINIMC_NODE_TH, 1U, 0U, 0U, sizeof(img), img_crc, 0U, tr};
+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_OTA_START, 82U, &bad_req);
+  require_true(s_last_tx[5] == MINIMC_CMD_NACK && boot_uart_ota_should_stay_in_boot() == 0U, "bad 0x20 unstayed");
+
+  minimc_payload_ota_start_t ok_req = {MINIMC_NODE_MC, 1U, 0U, 0U, sizeof(img), img_crc, 0U, tr};
+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_OTA_START, 83U, &ok_req);
+  require_true(s_last_tx[5] == MINIMC_CMD_ACK && boot_uart_ota_should_stay_in_boot() == 1U, "0x20 stays");
+  send_ota_data_chunk(84U, 0U, &img[0]);
+  send_ota_data_chunk(85U, 512U, &img[512]);
+  minimc_payload_ota_finish_t fin_req = {img_crc, 1U, {0U, 0U, 0U}};
+  send_minimc_frame(MINIMC_NODE_MC, MINIMC_CMD_OTA_FINISH, 86U, &fin_req);
+  require_true(s_last_tx[5] == MINIMC_CMD_ACK && s_jump_count == 1U, "explicit 0x20 OTA commits & jumps");
+}
+
 /**
   * @brief  测试主入口
+  * @param  无
+  * @return 0 表示全部测试通过
   */
 int main(void)
 {
   test_magic_info_heartbeat_and_dst_filter();
+  test_cold_boot_continuous_poll_allows_app_jump();
+  test_explicit_stay_in_boot_triggers();
   test_single_writer_mutex_and_zero_erase_admission();
   test_full_ota_flow_and_crc_verification();
   test_interbyte_timeout_and_crc_nack_recovery();

