+    返回:
+        bool: 若本次写入了迁移标记或更新了语言返回 True，无需修改返回 False。
+    """
+    if not isinstance(data, dict) or default_lang != 'zh':
+        return False
+    if 'c308l_default_lang_migrated' in data:
+        return False
+    # 仅在首次升级且原语言为空或存量默认英文时切为中文，后续用户手动切回英文不再覆盖。
+    cur_lang = data.get('language', '')
+    if cur_lang in ('', 'en', None):
+        data['language'] = 'zh'
+    data['c308l_default_lang_migrated'] = 1
+    return True
+
+
+def sync_panel_backup_language(panel_config: Path, default_lang: str) -> None:
