+    try:
+        backup_data = json.loads(backup_file.read_text(encoding='utf-8'))
+    except (OSError, ValueError):
+        return
+    if migrate_default_language_once(backup_data, default_lang):
+        _write_json_atomic(backup_file, backup_data)
