 16	/** @brief 返回当前状态 JSON 的总体百分比；按所选镜像大小加权，节点切换不回退。 */
 17	static uint32_t total_percent(const fwd_ota_runtime* rt) {
 18	    if (rt == nullptr) return 0U;
 19	    uint64_t total = 0U;
 20	    uint64_t completed = 0U;
 21	    for (size_t index = 0U; index < 2U; ++index) {
 22	        if ((rt->mask & (1U << index)) == 0U) continue;
 23	        total += rt->image[index].size;
 24	        completed += static_cast<uint64_t>(rt->image[index].size) * rt->percent[index];
 25	    }
 26	    return total == 0U ? 0U : static_cast<uint32_t>(completed / total);
 27	}
