 35	/** @brief 仅在持 runtime.mutex 时序列化定长快照；所有字符串来自固定码或十六进制摘要。 */
 36	static void build_snapshot(fwd_ota_runtime* rt) {
 37	    if (rt == nullptr) return;
 38	    timespec timestamp = {};
 39	    clock_gettime(CLOCK_REALTIME, &timestamp);
 40	    const auto timestamp_ms = static_cast<uint64_t>(timestamp.tv_sec) * 1000U + timestamp.tv_nsec / 1000000U;
 41	    const char* mc_state = rt->scan_state[0][0] != '\0' ? rt->scan_state[0] : "UNSCANNED";
 42	    const char* th_state = rt->scan_state[1][0] != '\0' ? rt->scan_state[1] : "UNSCANNED";
 43	    std::snprintf(rt->latest.json, sizeof(rt->latest.json),
 44	        "{\"schema_version\":1,\"policy\":\"%s\",\"timestamp_unix_ms\":%llu,\"last_sequence\":%u,\"last_elapsed_ms\":%u,\"task_id\":\"%llu\",\"event_id\":%llu,\"phase\":\"%s\",\"active\":%s,"
 45	        "\"communication_error\":%d,\"failed_node\":%u,\"failed_command\":%u,\"maintenance\":%s,\"target_mask\":%u,\"active_node\":%u,\"progress_pct\":%u,\"error\":\"%s\","
 46	        "\"mc\":{\"valid\":%s,\"scan_state\":\"%s\",\"scan_error\":\"%s\",\"file\":\"fw_mc.bin\",\"size\":%u,\"version_raw\":%u,\"sha256\":\"%s\","
 47	        "\"progress_pct\":%u,\"received\":%u,\"written\":%u,\"pre_boot_id\":%u,\"post_boot_id\":%u,\"warning\":\"%s\"},"
 48	        "\"th\":{\"valid\":%s,\"scan_state\":\"%s\",\"scan_error\":\"%s\",\"file\":\"fw_th.bin\",\"size\":%u,\"version_raw\":%u,\"sha256\":\"%s\","
 49	        "\"progress_pct\":%u,\"received\":%u,\"written\":%u,\"pre_boot_id\":%u,\"post_boot_id\":%u,\"warning\":\"%s\"}}",
 50	        kOtaPolicy, static_cast<unsigned long long>(timestamp_ms), rt->last_sequence, rt->last_elapsed_ms,
 51	        static_cast<unsigned long long>(rt->task_id), static_cast<unsigned long long>(rt->event_id),
 52	        rt->phase, rt->active ? "true" : "false", rt->communication_error, rt->failed_node, rt->failed_command,
 53	        rt->active || rt->recovery_pending ? "true" : "false",
 54	        rt->mask, 2U + rt->current, total_percent(rt), rt->error,
 55	        rt->image[0].valid ? "true" : "false", mc_state, rt->scan_error[0], rt->image[0].size, rt->image[0].version, rt->image[0].sha256,
 56	        rt->percent[0], rt->received[0], rt->written[0], rt->pre_boot[0], rt->post_boot[0], rt->warning[0],
 57	        rt->image[1].valid ? "true" : "false", th_state, rt->scan_error[1], rt->image[1].size, rt->image[1].version, rt->image[1].sha256,
 58	        rt->percent[1], rt->received[1], rt->written[1], rt->pre_boot[1], rt->post_boot[1], rt->warning[1]);
 59	}
