128	/** @brief rt 为已结束任务；优先报告锁存的通信错误，保留首个故障节点/命令/序号。 */
129	static const char* task_error(const fwd_ota_runtime* rt) {
130	    if (rt == nullptr) return "INVALID_TASK";
131	    switch (rt->communication_error) {
132	        case AISOC_FWD_ERR_SERIAL_OPEN: return "SERIAL_NOT_READY";
133	        case AISOC_FWD_ERR_SERIAL_IO: return "SERIAL_IO_ERROR";
134	        case AISOC_FWD_ERR_TIMEOUT: return "SERIAL_TIMEOUT";
135	        case AISOC_FWD_ERR_NACK: return "REMOTE_NACK";
136	        case AISOC_FWD_OK: break;
137	        default: return "COMMUNICATION_FAILED";
138	    }
139	    return rt->error[0] == '\0' ? "UPGRADE_INTERRUPTED" : rt->error;
140	}
