165	/** @brief context 为静态服务槽；在自己的线程执行文件与协议闭环，退出返回空。 */
166	static void* worker_main(void* context) {
167	    if (context == nullptr) return nullptr;
168	    auto* rt = static_cast<fwd_ota_runtime*>(context);
169	    while (true) {
170	        pthread_mutex_lock(&rt->mutex);
171	        while (!rt->pending && !rt->stopping) {
172	            pthread_cond_wait(&rt->wake, &rt->mutex);
173	        }
174	        if (rt->stopping) {
175	            pthread_mutex_unlock(&rt->mutex);
176	            break;
177	        }
178	        rt->pending = false;
179	        pthread_mutex_unlock(&rt->mutex);
180	        execute_task(rt);
181	    }
182	    return nullptr;
183	}
