185	/** @brief context 为服务槽；仅复制最新快照，DDS 写入不占 UART 或任务锁。 */
186	static void* reporter_main(void* context) {
187	    if (context == nullptr) return nullptr;
188	    auto* rt = static_cast<fwd_ota_runtime*>(context);
189	    while (true) {
190	        aisoc_ota_status_t sample = {};
191	        pthread_mutex_lock(&rt->mutex);
192	        while (rt->published_id == rt->event_id && !rt->stopping) {
193	            pthread_cond_wait(&rt->wake, &rt->mutex);
194	        }
195	        if (rt->stopping) {
196	            pthread_mutex_unlock(&rt->mutex);
197	            break;
198	        }
199	        sample = rt->latest;
200	        rt->published_id = rt->event_id;
201	        pthread_mutex_unlock(&rt->mutex);
202	        const auto status = aisoc_dds_publish_ota_status(rt->publisher, &sample);
203	        if (status != AISOC_DDS_OK) std::fprintf(stderr, "[OTA_DDS] error_code=%d\n", status);
204	    }
205	    return nullptr;
206	}
