208	/** @brief text 为扫描所得64字符小写摘要；返回格式是否完整，不接受路径或任意字符串。 */
209	static bool valid_hash(const char* text) {
210	    if (text == nullptr || std::strlen(text) != 64U) return false;
211	    for (size_t index = 0U; index < 64U; ++index) {
212	        const bool lower = text[index] >= 'a' && text[index] <= 'f';
213	        const bool digit = text[index] >= '0' && text[index] <= '9';
214	        if (!lower && !digit) return false;
215	    }
216	    return true;
217	}
