249	aisoc_fwd_status_t fwd_ota_command(forward_service_state_t* state,
250	    const fwd_ota_command_request* request, uint64_t* out_task) {
251	    if (state == nullptr || request == nullptr || out_task == nullptr) return AISOC_FWD_ERR_NULL_PTR;
252	    if (state->ota == nullptr) return AISOC_FWD_ERR_BUSY;
253	    if (request->operation > 1U || request->target_mask < 1U || request->target_mask > 3U)
254	        return AISOC_FWD_ERR_INVALID_ARG;
255	    if (request->operation == 1U) {
256	        if (!request->confirmed_safe) return AISOC_FWD_ERR_INVALID_ARG;
257	        if ((request->target_mask & 1U) != 0U && !valid_hash(request->mc_sha256)) return AISOC_FWD_ERR_INVALID_ARG;
258	        if ((request->target_mask & 2U) != 0U && !valid_hash(request->th_sha256)) return AISOC_FWD_ERR_INVALID_ARG;
259	    }
260	    auto* rt = state->ota;
261	    pthread_mutex_lock(&rt->mutex);
262	    if (rt->active || rt->stopping) {
263	        pthread_mutex_unlock(&rt->mutex);
264	        return AISOC_FWD_ERR_BUSY;
265	    }
266	    prepare_command(rt, request);
267	    *out_task = rt->task_id;
268	    pthread_cond_broadcast(&rt->wake);
269	    pthread_mutex_unlock(&rt->mutex);
270	    return AISOC_FWD_OK;
271	}
