273	aisoc_fwd_status_t fwd_ota_service_start(forward_service_state_t* state) {
274	    if (state == nullptr) return AISOC_FWD_ERR_NULL_PTR;
275	    if (runtime.owner != nullptr) return AISOC_FWD_ERR_BUSY;
276	    auto* rt = &runtime;
277	    *rt = {};
278	    if (pthread_mutex_init(&rt->mutex, nullptr) != 0) return AISOC_FWD_ERR_SERIAL_IO;
279	    if (pthread_cond_init(&rt->wake, nullptr) != 0) {
280	        pthread_mutex_destroy(&rt->mutex);
281	        return AISOC_FWD_ERR_SERIAL_IO;
282	    }
283	    rt->initialized = true;
284	    rt->owner = state;
285	    rt->phase = "IDLE";
286	    rt->error = "";
287	    rt->task_id = static_cast<uint64_t>(std::time(nullptr)) * 1000000U;
288	    rt->image[0] = {mc_image, sizeof(mc_image), 0U, 0U, 0U, false, {0}};
289	    rt->image[1] = {th_image, sizeof(th_image), 0U, 0U, 0U, false, {0}};
290	    std::snprintf(rt->scan_state[0], sizeof(rt->scan_state[0]), "UNSCANNED");
291	    std::snprintf(rt->scan_state[1], sizeof(rt->scan_state[1]), "UNSCANNED");
292	    state->ota = rt;
293	    const aisoc_dds_publisher_config_t config = {AISOC_TOPIC_OTA_STATUS, AISOC_DDS_QOS_RELIABLE_TRANSIENT_LOCAL};
294	    const auto status = aisoc_dds_publisher_create(state->dds_participant, &config, &rt->publisher);
295	    if (status != AISOC_DDS_OK) {
296	        fwd_ota_service_stop(state);
297	        return AISOC_FWD_ERR_DDS_INIT;
298	    }
299	    if (pthread_create(&rt->worker, nullptr, worker_main, rt) != 0) {
300	        fwd_ota_service_stop(state);
301	        return AISOC_FWD_ERR_SERIAL_IO;
302	    }
303	    rt->worker_started = true;
304	    if (pthread_create(&rt->reporter, nullptr, reporter_main, rt) != 0) {
305	        fwd_ota_service_stop(state);
306	        return AISOC_FWD_ERR_SERIAL_IO;
307	    }
308	    rt->reporter_started = true;
309	    ota_emit(rt, "IDLE", "");
310	    return AISOC_FWD_OK;
311	}
