313	void fwd_ota_service_stop(forward_service_state_t* state) {
314	    if (state == nullptr || state->ota == nullptr) return;
315	    auto* rt = state->ota;
316	    pthread_mutex_lock(&rt->mutex);
317	    rt->stopping = true;
318	    pthread_cond_broadcast(&rt->wake);
319	    pthread_mutex_unlock(&rt->mutex);
320	    if (rt->worker_started) pthread_join(rt->worker, nullptr);
321	    if (rt->reporter_started) pthread_join(rt->reporter, nullptr);
322	    if (rt->publisher != nullptr) aisoc_dds_publisher_destroy(rt->publisher);
323	    pthread_cond_destroy(&rt->wake);
324	    pthread_mutex_destroy(&rt->mutex);
325	    state->ota = nullptr;
326	    *rt = {};
327	}
