329	aisoc_dbus_status_t fwd_ota_dbus_command(const aisoc_dbus_msg_t* req,
330	    aisoc_dbus_msg_t* reply, void* context) {
331	    if (req == nullptr || reply == nullptr || context == nullptr) return AISOC_DBUS_ERR_NULL_PTR;
332	    fwd_ota_command_request command = {};
333	    aisoc_dbus_iter_t iter;
334	    aisoc_dbus_iter_init(req, &iter);
335	    if (aisoc_dbus_iter_get_byte(&iter, &command.operation) != AISOC_DBUS_OK) return AISOC_DBUS_ERR_INVALID_PARAM;
336	    if (aisoc_dbus_iter_get_byte(&iter, &command.target_mask) != AISOC_DBUS_OK) return AISOC_DBUS_ERR_INVALID_PARAM;
337	    if (aisoc_dbus_iter_get_bool(&iter, &command.confirmed_safe) != AISOC_DBUS_OK) return AISOC_DBUS_ERR_INVALID_PARAM;
338	    if (aisoc_dbus_iter_get_bool(&iter, &command.allow_reflash) != AISOC_DBUS_OK) return AISOC_DBUS_ERR_INVALID_PARAM;
339	    if (aisoc_dbus_iter_get_string(&iter, &command.mc_sha256) != AISOC_DBUS_OK) return AISOC_DBUS_ERR_INVALID_PARAM;
340	    if (aisoc_dbus_iter_get_string(&iter, &command.th_sha256) != AISOC_DBUS_OK) return AISOC_DBUS_ERR_INVALID_PARAM;
341	    if (iter.is_valid) return AISOC_DBUS_ERR_INVALID_PARAM;
342	    uint64_t task = 0U;
343	    const auto status = fwd_ota_command(static_cast<forward_service_state_t*>(context), &command, &task);
344	    aisoc_dbus_msg_append_int32(reply, status);
345	    aisoc_dbus_msg_append_uint64(reply, task);
346	    return AISOC_DBUS_OK;
347	}

