175	void OtaLocalOverlay::sync_from_backend() {
176	#ifdef HELIX_ENABLE_AISOC
177	    auto* conn = helix::aisoc::active_aisoc_connection();
178	    if (!conn || !subjects_initialized_) return;
179	    const auto st = conn->ota_status();
180	    const auto snap = conn->snapshot();
181	    // RPC 刚受理但尚未收到新 task 首个 DDS 事件（event_id==0）时跳过旧残影覆盖，等待真实 DDS 状态。
182	    if (!st.task_id.empty() && st.event_id == 0U && st.last_rpc_code == 0) return;
183	    // 严格同步当前扫描结果，防止移除固件重扫后残留旧 SHA-256。
184	    scanned_mc_sha256_ = st.mc.valid ? st.mc.sha256 : std::string();
185	    scanned_th_sha256_ = st.th.valid ? st.th.sha256 : std::string();
186	    const std::string phase_str = format_ota_phase(st);
187	    const std::string mc_str = format_ota_pkg("fw_mc.bin", st.mc);
188	    const std::string th_str = format_ota_pkg("fw_th.bin", st.th);
189	    lv_subject_copy_string(&phase_subject_, phase_str.c_str());
190	    lv_subject_copy_string(&mc_pkg_subject_, mc_str.c_str());
191	    lv_subject_copy_string(&th_pkg_subject_, th_str.c_str());
192	    lv_subject_set_int(&progress_subject_, static_cast<int32_t>(st.progress_pct));
193	    if (scan_feedback_pending_) {
194	        // 1280x720 滚至底部点击扫描时顶部状态行不在视口内，终态到达时弹出即时 Toast 反馈。
195	        const bool scan_done = !st.active && (st.phase == "READY" || st.phase == "FAILED");
196	        if (scan_done || st.last_rpc_code != 0) {
197	            scan_feedback_pending_ = false;
198	            const auto sev = (st.phase == "READY" && st.last_rpc_code == 0)
199	                                 ? ToastSeverity::SUCCESS
200	                                 : ToastSeverity::WARNING;
201	            ToastManager::instance().show(sev, phase_str.c_str(), 2800);
202	        }
203	    }
204	    const bool busy = (snap.last_estop_outcome == helix::aisoc::AisocEstopOutcome::BACKEND_BUSY) ||
205	                      (st.last_rpc_code == -5) || st.active || st.maintenance;
206	    if (busy) {
207	        set_lock_hint("状态: 后台已锁定 (BUSY)");
208	    } else if (snap.last_estop_outcome == helix::aisoc::AisocEstopOutcome::CONFIRMED || snap.estop_latched) {
209	        set_lock_hint("状态: 设备已确认急停");
210	    } else if (!snap.dm_connected) {
211	        set_lock_hint("状态: 本地服务未连接（请检查后台服务后重试）");
212	    } else if (!snap.mc.online || !snap.th.online) {
213	        set_lock_hint("状态: 节点离线（请检查板卡连接待恢复 ONLINE 后重试）");
214	    } else {
215	        set_lock_hint("状态: 就绪");
216	    }
217	#endif
218	}
