220	void OtaLocalOverlay::handle_scan() {
221	#ifdef HELIX_ENABLE_AISOC
222	    auto* conn = helix::aisoc::active_aisoc_connection();
223	    if (!conn) {
224	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
225	        return;
226	    }
227	    const auto st = conn->ota_status();
228	    if (st.active || st.maintenance) {
229	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 后台已锁定 (BUSY)", 2000);
230	        return;
231	    }
232	    scan_feedback_pending_ = true;
233	    helix::aisoc::AisocOtaRequest req;
234	    req.operation = 0U;
235	    req.target_mask = 3U;
236	    conn->request_ota(req);
237	#endif
238	}
