240	void OtaLocalOverlay::handle_start_upgrade() {
241	#ifdef HELIX_ENABLE_AISOC
242	    auto* conn = helix::aisoc::active_aisoc_connection();
243	    if (!conn) {
244	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
245	        return;
246	    }
247	    const uint8_t mask = static_cast<uint8_t>((select_mc_ ? 1U : 0U) | (select_th_ ? 2U : 0U));
248	    if (mask == 0U || !confirmed_safe_) {
249	        ToastManager::instance().show(ToastSeverity::WARNING, "请选择升级节点并开启安全前置确认", 2500);
250	        return;
251	    }
252	    const auto st = conn->ota_status();
253	    const auto snap = conn->snapshot();
254	    if (st.active || st.maintenance) {
255	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 后台已锁定 (BUSY)", 2000);
256	        return;
257	    }
258	    // 仅校验当前所选节点是否已通过扫描校验，允许取消缺失板后单板升级已就绪节点。
259	    const bool mc_ready = ((mask & 1U) == 0U) || (st.mc.valid && !st.mc.sha256.empty());
260	    const bool th_ready = ((mask & 2U) == 0U) || (st.th.valid && !st.th.sha256.empty());
261	    if (!mc_ready || !th_ready) {
262	        ToastManager::instance().show(ToastSeverity::WARNING, "请先扫描固件并确认所选节点固件包校验通过", 2500);
263	        return;
264	    }
265	    if (!snap.dm_connected) {
266	        ToastManager::instance().show(ToastSeverity::ERROR, "状态: 本地服务未连接（请检查后台服务后重试）", 2500);
267	        return;
268	    }
269	    const bool mc_online = ((mask & 1U) == 0U) || snap.mc.online;
270	    const bool th_online = ((mask & 2U) == 0U) || snap.th.online;
271	    if (!mc_online || !th_online) {
272	        ToastManager::instance().show(ToastSeverity::WARNING, "状态: 节点离线（请检查板卡连接待恢复 ONLINE 后重试）", 2500);
273	        return;
274	    }
275	    scan_feedback_pending_ = false;
276	    helix::aisoc::AisocOtaRequest req;
277	    req.operation = 1U;
278	    req.target_mask = mask;
279	    req.confirmed_safe = true;
280	    req.allow_reflash = allow_reflash_;
281	    req.mc_sha256 = ((mask & 1U) != 0U) ? st.mc.sha256 : std::string();
282	    req.th_sha256 = ((mask & 2U) != 0U) ? st.th.sha256 : std::string();
283	    conn->request_ota(req);
284	#endif
285	}
