void AisocConnection::set_estop_callback(EstopCallback cb) {
    std::lock_guard<std::mutex> lock(mutex_);
    estop_cb_ = std::move(cb);
}

void AisocConnection::set_ota_callback(OtaStatusCallback cb) {
    std::lock_guard<std::mutex> lock(mutex_);
    ota_cb_ = std::move(cb);
}

void AisocConnection::request_refresh() {
    std::lock_guard<std::mutex> lock(mutex_);
    refresh_requested_ = true;
    cv_.notify_all();
}

void AisocConnection::request_emergency_stop(bool engage) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (stop_requested_) return;
    estop_queue_.push_back(engage);
    cv_.notify_all();
}

void AisocConnection::request_ota(const AisocOtaRequest& req) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (stop_requested_) return;
    ota_queue_.push_back(req);
    cv_.notify_all();
}

void AisocConnection::worker_loop() {
    while (true) {
        process_pending_estops();
        process_pending_ota();
        poll_ota_dds();
        bool do_refresh = false;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stop_requested_) break;
            do_refresh = refresh_requested_;
            refresh_requested_ = false;
        }
        poll_once();
        poll_ota_dds();
        if (do_refresh) process_pending_estops();
        std::unique_lock<std::mutex> lock(mutex_);
        if (stop_requested_) break;
        uint32_t wait_ms = config_.poll_interval_ms > 0U ? config_.poll_interval_ms : 1000U;
        if ((ota_status_.active || pending_reboot_verify_) && wait_ms > 80U) wait_ms = 80U;
        cv_.wait_for(lock, std::chrono::milliseconds(wait_ms), [this]() {
            return stop_requested_ || refresh_requested_ || !estop_queue_.empty() || !ota_queue_.empty();
        });
        if (stop_requested_) break;
    }
}

void AisocConnection::process_pending_estops() {
    while (true) {
        bool engage = true;
        EstopCallback cb;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stop_requested_ || estop_queue_.empty()) return;
            engage = estop_queue_.front();
            estop_queue_.erase(estop_queue_.begin());
            cb = estop_cb_;
        }
        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
        const AisocEstopResult res = execute_dm_estop(conn, engage, config_.rpc_timeout_ms);
        if (res.outcome == AisocEstopOutcome::DISCONNECTED) close_dbus(&dbus_handle_);
        AisocSnapshot updated;
        AisocOtaStatus ota_snap;
        OtaStatusCallback ota_cb;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (res.outcome == AisocEstopOutcome::CONFIRMED) snapshot_.estop_latched = engage;
            snapshot_.last_estop_outcome = res.outcome;
            snapshot_.last_estop_detail = res.detail;
            updated = snapshot_;
            ota_snap = ota_status_;
            ota_cb = ota_cb_;
        }
        publish_if_changed(updated, true);
        if (ota_cb) ota_cb(ota_snap);
        if (cb) cb(res);
    }
}

void AisocConnection::process_pending_ota() {
    while (true) {
        AisocOtaRequest req;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stop_requested_ || ota_queue_.empty()) return;
            req = ota_queue_.front();
            ota_queue_.erase(ota_queue_.begin());
        }
        ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
        auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
        uint64_t task_id = 0U;
        const int32_t rc = execute_fwd_ota_command(conn, req, config_.rpc_timeout_ms, &task_id);
        AisocOtaStatus next;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            next = ota_status_;
            next.last_rpc_code = rc;
            if (rc == 0) {
                tracked_task_id_ = std::to_string(task_id);
                pending_reboot_verify_ = false;
                next.task_id = tracked_task_id_;
                next.event_id = 0U;
                next.reboot_verified = false;
                next.error.clear();
            } else if (rc == -5) {
                next.error = "BACKEND_BUSY";
            } else {
                next.error = "OTA_COMMAND_REJECTED";
            }
        }
        emit_ota_status(next);
    }
}

void AisocConnection::poll_ota_dds() {
    auto* sub = ensure_dds_ota(&dds_part_, &dds_ota_sub_, config_.dds_domain_id);
    if (sub == nullptr) return;
    aisoc_ota_status_t sample = {};
    for (uint32_t i = 0U; i < 32U; ++i) {
        if (aisoc_dds_take_ota_status(sub, &sample) != AISOC_DDS_OK) break;
        AisocOtaStatus parsed;
        if (!parse_ota_status_json(sample.json, &parsed)) continue;
        bool accept = false;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            const bool task_ok = tracked_task_id_.empty() || parsed.task_id == tracked_task_id_;
            const bool mono_ok = (parsed.task_id != ota_status_.task_id) ||
                                 (parsed.event_id > ota_status_.event_id);
            if (task_ok && mono_ok) {
                accept = true;
                parsed.last_rpc_code = ota_status_.last_rpc_code;
                parsed.reboot_verified = false;
                pending_reboot_verify_ = (parsed.phase == "SUCCEEDED");
            }
        }
        if (accept) emit_ota_status(parsed);
    }
}

void AisocConnection::verify_pending_ota_reboot(const McuNodeInfo& dm_mc, const McuNodeInfo& dm_th) {
    AisocOtaStatus verified;
    bool newly_verified = false;
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!pending_reboot_verify_ || ota_status_.phase != "SUCCEEDED") return;
        const uint32_t mask = ota_status_.target_mask;
        if (mask == 0U) return;
        const bool mc_ok = ((mask & 1U) == 0U) || node_reboot_verified(dm_mc, ota_status_.mc.pre_boot_id);
        const bool th_ok = ((mask & 2U) == 0U) || node_reboot_verified(dm_th, ota_status_.th.pre_boot_id);
        if (mc_ok && th_ok) {
            pending_reboot_verify_ = false;
            ota_status_.reboot_verified = true;
            verified = ota_status_;
            newly_verified = true;
        }
    }
    if (newly_verified) emit_ota_status(verified);
}

void AisocConnection::poll_once() {
    AisocSnapshot next;
    {
        std::lock_guard<std::mutex> lock(mutex_);
        next.ap = snapshot_.ap;
        next.estop_latched = snapshot_.estop_latched;
        next.last_estop_outcome = snapshot_.last_estop_outcome;
        next.last_estop_detail = snapshot_.last_estop_detail;
    }
    auto* conn = ensure_dbus(&dbus_handle_, config_.dbus_address);
    if (conn == nullptr) {
        next.device_state = "OFFLINE";
        next.system_status = "OFFLINE";
        publish_if_changed(next, false);
        return;
    }
    std::string ver_json;
    const aisoc_dbus_status_t ver_st = call_dm_string(conn, "GetVersionInfo", config_.rpc_timeout_ms, &ver_json);
    if (ver_st != AISOC_DBUS_OK || !parse_dm_version_json(ver_json, &next.mc, &next.th)) {
        if (ver_st == AISOC_DBUS_ERR_DISCONNECTED) close_dbus(&dbus_handle_);
        next.dm_connected = false;
        next.device_state = "OFFLINE";
        next.system_status = "OFFLINE";
        publish_if_changed(next, false);
        return;
    }
    next.dm_connected = true;
    verify_pending_ota_reboot(next.mc, next.th);
    std::string snap_json, state_json;
    if (call_dm_string(conn, "GetSnapshot", config_.rpc_timeout_ms, &snap_json) == AISOC_DBUS_OK) {
        parse_dm_snapshot_json(snap_json, &next);
    }
    if (call_dm_string(conn, "GetDeviceState", config_.rpc_timeout_ms, &state_json) == AISOC_DBUS_OK) {
        std::string state_str;
        if (detail::json_extract_string(state_json, "state", &state_str)) next.device_state = state_str;
    }
    if (!next.mc.online) {
        McuNodeInfo fwd_mc;
        if (query_forward_version(conn, 1U, config_.rpc_timeout_ms, &fwd_mc)) next.mc = fwd_mc;
    }
    publish_if_changed(next, false);
}

