/** @brief 向 DeviceInterface 发送 EmergencyStop 请求并区分 BACKEND_BUSY 与 CONFIRMED。 */
AisocEstopResult execute_dm_estop(aisoc_dbus_conn_t* conn, bool engage, int32_t timeout_ms) {
    AisocEstopResult res;
    res.engage = engage;
    if (conn == nullptr) { res.detail = "D-Bus 未连接"; return res; }
    const aisoc_dbus_method_call_t call = {
        AISOC_DBUS_BUS_NAME_DEVICE, AISOC_DBUS_PATH_DEVICE, AISOC_DBUS_IFACE_DEVICE, "EmergencyStop"};
    aisoc_dbus_msg_t req = {}, reply = {};
    if (aisoc_dbus_msg_init_call(&call, &req) != AISOC_DBUS_OK) {
        res.outcome = AisocEstopOutcome::FAILED;
        res.detail = "构造急停请求失败";
        return res;
    }
    aisoc_dbus_msg_append_byte(&req, engage ? 1U : 0U);
    const aisoc_dbus_call_opts_t opts = {timeout_ms > 800 ? timeout_ms : 800, true};
    const aisoc_dbus_status_t st = aisoc_dbus_call_method(conn, &req, &opts, &reply);
    aisoc_dbus_msg_unref(&req);
    if (st != AISOC_DBUS_OK) {
        res.error_code = static_cast<int32_t>(st);
        res.outcome = (st == AISOC_DBUS_ERR_DISCONNECTED || st == AISOC_DBUS_ERR_INTERNAL)
                          ? AisocEstopOutcome::DISCONNECTED : AisocEstopOutcome::FAILED;
        res.detail = (res.outcome == AisocEstopOutcome::DISCONNECTED) ? "后台服务未连接" : "急停 RPC 超时或失败";
        return res;
    }
    aisoc_dbus_iter_t it = {};
    aisoc_dbus_iter_init(&reply, &it);
    int32_t err_code = -1;
    const bool got = aisoc_dbus_iter_get_int32(&it, &err_code) == AISOC_DBUS_OK;
    aisoc_dbus_msg_unref(&reply);
    if (!got) { res.outcome = AisocEstopOutcome::FAILED; res.detail = "急停应答格式异常"; return res; }
    res.error_code = err_code;
    if (err_code == 0) {
        res.outcome = AisocEstopOutcome::CONFIRMED;
        res.detail = engage ? "设备已确认急停" : "设备已解除急停";
    } else if (err_code == -5) {
        res.outcome = AisocEstopOutcome::BACKEND_BUSY;
        res.detail = "后台已锁定 (BUSY)";
    } else {
        res.outcome = AisocEstopOutcome::FAILED;
        res.detail = "设备急停请求被拒绝或超时";
    }
    return res;
}

