/**
 * @brief 检查综合业务样本的源节点和受约束字段，防止错误 DDS 发布者绕过位图语义。
 * @param status [in] 非空候选业务状态。
 * @return 真表示字段范围合法，温度仍由后续通道质量门禁处理。
 */
static bool valid_device_status(const aisoc_device_status_t* status) {
    if (status == nullptr) return false;
    if (status->source_node != MINIMC_DEV_MC && status->source_node != MINIMC_DEV_SCM_TH) return false;
    if ((status->validity_bitmap & ~15U) != 0U || (status->sensor_fault_bitmap & ~7U) != 0U) return false;
    if (status->machine_state > 6U || status->homed_flags > 7U) return false;
    if (status->fan_speed > 255U || status->feedrate_percent > 255U) return false;
    return status->planner_free_slots <= 32U;
}

/**
 * @brief 主动事实可增加准入限制，不因一条 IDLE 自动撤销作业、故障或维护锁。
 * @param state [in,out] 已持状态锁的权威状态。
 * @param status [in] 已通过范围和时间检查的业务样本。
 * @param is_mc [in] 是否为主控报告。
 */
static void apply_status_safety(device_manager_state_t* state,
                                const aisoc_device_status_t* status, bool is_mc) {
    if (state == nullptr || status == nullptr) return;
    if (is_mc && (status->machine_state == 3U || status->machine_state == 4U)) state->is_printing = true;
    const size_t target = is_mc ? 1U : 0U;
    // 未知目标温度为正值哨兵，也保持保守约束；0x40 不包含 PWM，不能据此批准加热安全。
    if (status->target_temperature_millic[target] > 0) state->is_heating = true;
    if (is_mc && status->machine_state >= 5U) {
        state->is_fault = true;
        strncpy(state->device_state, "FAULT", sizeof(state->device_state) - 1U);
        strncpy(state->snapshot.system_status_desc, "FAULT", sizeof(state->snapshot.system_status_desc) - 1U);
    }
}

